// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file may or may not exist when type-checking
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import openNextWorker from "./.open-next/worker.js";

// Next marks prerendered pages and their RSC payloads `s-maxage=…, stale-while-revalidate=…`. Browsers honour the
// stale-while-revalidate part, so after a deploy they show a cached page from the previous build whose CSS chunks no
// longer exist (404). Pages must be revalidated on every visit instead (cheap: the ETag turns it into a 304).
export default {
  async fetch(request, env, ctx) {
    const response: Response = await openNextWorker.fetch(request, env, ctx);
    if (!response.headers.get("Cache-Control")?.includes("s-maxage")) return response;

    const headers = new Headers(response.headers);
    headers.set("Cache-Control", "public, max-age=0, must-revalidate");
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
  }
} satisfies ExportedHandler<CloudflareEnv>;
